export const meta = {
  name: 'work-shelf-tickets',
  description: 'Implement B3, B4, B6, F3 in shelf repo, then independently review and fix',
  phases: [{ title: 'Implement' }, { title: 'Review' }, { title: 'Fix' }],
}
const REPO = args.repo
const CTX = `Repo: ${REPO} (Python, run tests with \`python -m pytest -q\` from the repo root). Board is TICKETS.md. Do NOT commit, do NOT touch F2/F5/F7 or create shelf/export.py. Match existing code style (small, plain, minimal comments).`
const TICKETS = `
- B3: books.add("", "Herbert") must raise ValueError for a blank title (treat whitespace-only as blank too). shelf/books.py
- B4: books.find must be case-insensitive ("dune" finds "Dune"). shelf/books.py
- B6: \`list --json\` on an empty shelf must print \`[]\` (the nightly sync job json.loads() the output; empty output crashes it). shelf/cli.py
- F3: report.by_author() returns {author: count}. shelf/report.py`

phase('Implement')
const impl = await agent(`${CTX}
Implement these tickets, each with a regression test in tests/test_books.py:${TICKETS}
Then update TICKETS.md: mark B3, B4, B6, F3 as [x] with a short note of what was done (keep IDs/order; for B6 note the decision "print []: empty output also fails json.loads"). Also mark F2 and F5 as [!] blocked with reason "awaiting owner: CSV vs JSON format" (F5: "depends on F2").
Run the full test suite. Return a concise summary: files changed, tests added, final pytest output line.`, { label: 'implement', phase: 'Implement' })

phase('Review')
const review = await agent(`${CTX}
Independently review the uncommitted changes (\`git diff\`) against these tickets:${TICKETS}
Check correctness, edge cases (e.g. None title, whitespace, find with mixed case query, CLI json output for empty and non-empty), that tests actually cover the tickets, and that TICKETS.md updates are accurate and follow the legend. Run the tests. Do not edit files.`, {
  label: 'review', phase: 'Review',
  schema: { type: 'object', properties: {
    tests_pass: { type: 'boolean' },
    issues: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['file', 'problem', 'fix'] } }
  }, required: ['tests_pass', 'issues'] }
})

let fix = null
if (review && (review.issues.length || !review.tests_pass)) {
  phase('Fix')
  fix = await agent(`${CTX}
A reviewer raised these issues on the uncommitted changes. Fix the ones that are genuine (skip and explain any you judge wrong), rerun tests, and return a summary:
${JSON.stringify(review.issues, null, 2)}`, { label: 'fix', phase: 'Fix' })
}
return { impl, review, fix }

